NAME = 'SloKJV: Slovenian translation of Holy Bible King James Version (1769)'
BOOK = 'Hebrews'

CHAPTERS = {
    1: {
        1: 'Bog, ki je ob različnih časih in na številne načine v preteklem času govoril očetom po prerokih,',
        2: 'nam je v teh poslednjih dneh spregovoril po svojem Sinu, ki ga je določil [za] dediča vseh stvari, po katerem je tudi naredil svetove;',
        3: 'ki je sijaj njegove slave in natančna podoba njegove osebe in po besedi svoje moči nosi vse stvari; ko nas je po sebi očistil naših grehov, je sédel na desnico Veličanstva na višavi;',
        4: 'narejen je bil toliko boljši kakor angeli, kolikor je s podedovanjem dosegel odličnejše ime kakor oni.',
        5: 'Kajti kateremu izmed angelov je on kadarkoli rekel: »Ti si moj Sin, danes sem te rodil?« In ponovno: »Jaz mu bom Oče in on mi bo Sin?«',
        6: 'In ponovno, ko privede prvorojenca na svet, pravi: »In obožujejo naj ga vsi Božji angeli.«',
        7: '§ In o angelih pravi: »Kdor dela svoje angele duhove in svoje služabnike ognjene plamene.«',
        8: 'Toda sinu pravi: »Tvoj prestol, oh Bog, je na veke vekov; žezlo pravičnosti je žezlo tvojega kraljestva.«',
        9: 'Ljubil si pravičnost in sovražil krivičnost; zatorej te je Bog, celó tvoj Bog, mazilil z oljem veselja bolj kakor tvoje tovariše.',
        10: 'In: »Ti, Gospod, si v začetku položil temelj zemlji in nebesa so delo tvojih rok;',
        11: 'ona bosta propadla, toda ti ostajaš; in vsa se bosta postarala kakor obleka;',
        12: 'in zložil ju boš kakor suknjo in se bosta spremenila, toda ti si isti in tvoja leta ne bodo prenehala.«',
        13: 'Toda kateremu izmed angelov je ob kateremkoli času rekel: »Sédi na mojo desnico, dokler ne naredim tvojih sovražnikov [za] tvojo pručko?«',
        14: 'Mar niso vsi ti službujoči duhovi, poslani, da služijo zaradi tistih, ki bodo dediči rešitve duš?',
    },
    2: {
        1: 'Zatorej smo dolžni dati iskrenejšo pozornost besedam, ki smo jih slišali, da jim ne bi kadarkoli pustili izmuzniti se.',
        2: 'Kajti če je bila beseda, govorjena po angelih, neomajna in je vsak prestopek ter neposlušnost prejel pravično povračilo nagrade;',
        3: 'kako bomo ušli mi, če zanemarimo tako veliko rešitev duš, o kateri je najprej začel govoriti Gospod in nam je bila potrjena po tistih, ki smo ga slišali;',
        4: '[ko] njim Bog prav tako prinaša pričevanje, tako z znamenji kakor s čudeži in z različnimi čudežnimi močmi ter darovi Svetega Duha, glede na svojo lastno voljo?',
        5: 'Kajti angelom ni položil v podreditev sveta, ki pride, o katerem govorimo.',
        6: 'Temveč je nekdo na nekem kraju pričeval, rekoč: »Kaj je človek, da misliš nanj? Ali človeški sin, da ga obiskuješ?',
        7: '§ Naredil si ga malo nižjega od angelov; kronaš ga s slavo in častjo in postavljaš ga nad dela svojih rok.',
        8: 'Vse stvari si podvrgel pod njegova stopala.« Kajti ker je vse podvrgel pod njega, ni pustil ničesar, kar ni položeno pod njega. Vendar sedaj še ne vidimo vseh stvari položenih pod njega.',
        9: 'Toda vidimo Jezusa, ki je bil postavljen malo nižje od angelov, zaradi smrtnega trpljenja, kronanega s slavo in častjo; da bi po Božji milosti okusil smrt za vsakega človeka.',
        10: 'Kajti spodobilo se je njemu, za katerega so vse stvari in po katerem so vse stvari v prinašanju mnogih sinov v slavo, da naredi poveljnika njihove rešitve duš popolnega skozi trpljenja.',
        11: 'Kajti vsi so iz enega, tako kdor posvečuje kakor tisti, ki so posvečeni. Zaradi tega razloga ni osramočen, da jih kliče brate,',
        12: 'rekoč: »Oznanjal bom tvoje ime svojim bratom, na sredi cerkve ti bom prepeval hvalo.«',
        13: 'In ponovno: »Svoje trdno upanje bom položil vanj.« In ponovno: »Glej, jaz in otroci, ki mi jih je dal Bog.«',
        14: 'Ker ste potem kot otroci soudeleženci mesa in krvi, je tudi sam prav tako vzel del od istega, da bi skozi smrt lahko uničil tistega, ki je imel smrtno oblast, to je hudiča',
        15: 'in osvobodil tiste, ki so bili zaradi strahu pred smrtjo vse svoje življenje podrejeni sužnosti.',
        16: 'Kajti resnično nase ni prevzel narave angelov, temveč je nase prevzel Abrahamovo seme.',
        17: '§ Zatorej se je zanj v vseh stvareh spodobilo, da je bil narejen podoben svojim bratom, da bi bil lahko usmiljen in zvest véliki duhovnik v stvareh, ki se nanašajo na Boga, da opravi pobotanje za grehe ljudi.',
        18: 'Kajti ker je on sam trpel in bil skušan, je zmožen okrepiti te, ki so skušani.',
    },
    3: {
        1: '§ Zatorej sveti bratje, soudeleženci nebeške poklicanosti, preudarite Apostola in Vélikega Duhovnika naše veroizpovedi, Kristusa Jezusa,',
        2: 'ki je bil zvest tistemu, ki ga je določil, kakor je bil tudi Mojzes zvest v vsej njegovi hiši.',
        3: 'Kajti ta človek je bil štet za vrednega večje slave kakor Mojzes, ker kdor je hišo zgradil, ima večjo čast kakor hiša.',
        4: 'Kajti vsaka hiša je zgrajena po nekem človeku, toda kdor je zgradil vse stvari, je Bog.',
        5: 'In Mojzes je bil resnično zvest v vsej njegovi hiši kot služabnik, za pričevanje o teh stvareh, o katerih naj bi se pozneje govorilo;',
        6: '§ toda Kristus [pa] kot sin nad svojo lastno hišo; katerega hiša smo mi, če trdno držimo zaupanje in se trdno veselimo upanja do konca.',
        7: 'Zatorej (kakor govori Sveti Duh: »Če boste danes zaslišali njegov glas,',
        8: 'ne zakrknite svojih src kakor v izzivanju, na dan preizkušnje v divjini,',
        9: 'ko so me vaši očetje skušali, me presojali in štirideset let gledali moja dela.«',
        10: 'Zato sem bil užaloščen s tem rodom in rekel: »Vedno se motijo v svojem srcu in niso spoznali mojih poti.«',
        11: 'Tako sem prisegel v svojem besu: »Ne bodo vstopili v moj počitek.«)',
        12: 'Pazite bratje, da ne bi bilo v katerem izmed vas hudobno srce nevere v umikanju od živega Boga.',
        13: 'Temveč vsakodnevno drug drugega spodbujajte, dokler se imenuje: »Danes,« da ne bi kdorkoli izmed vas zakrknil zaradi zapeljivosti greha.',
        14: 'Kajti postali smo Kristusovi soudeleženci, če začetek našega zaupanja neomajno držimo do konca;',
        15: 'dokler je rečeno: »Če boste danes zaslišali njegov glas, ne zakrknite svojih src kakor v izzivanju.«',
        16: '§ Kajti nekateri, ko so slišali, so izzivali; čeprav ne vsi, ki so prišli po Mojzesu iz Egipta.',
        17: 'Toda nad kom je bil štirideset let užaloščen? Mar ni bil s temi, ki so grešili, katerih trupla so popadala v divjini?',
        18: 'In katerim je prisegel, da naj ne bi vstopili v njegov počitek, če ne tem, ki niso verovali?',
        19: 'Tako vidimo, da niso mogli vstopiti zaradi nevere.',
    },
    4: {
        1: 'Bojmo se torej, da se ne bi komurkoli izmed vas zdelo, da je zamudil obljubo o vstopu v njegov počitek, ki nam je bila zapuščena.',
        2: 'Kajti evangelij je bil oznanjen nam kakor tudi njim. Toda oznanjena beseda tem ni koristila, ker ni bila pridružena veri tistih, ki so jo slišali.',
        3: 'Kajti mi, ki smo verovali, vstopamo v počitek, kakor pravi: »Kakor sem prisegel v svojem besu, če bodo vstopili v moj počitek;« čeprav so bila dela končana od ustanovitve sveta.',
        4: 'Kajti na nekem mestu je o sedmem dnevu govoril na ta način: »In Bog je počival sedmi dan od vseh svojih del.«',
        5: 'In na tem mestu ponovno: »Če bodo vstopili v moj počitek.«',
        6: 'Ker torej ostaja to, da morajo nekateri vstopiti vanj in tisti, ki jim je bilo to najprej oznanjeno, zaradi nevere niso vstopili;',
        7: 'znova omejuje nek dan, rekoč v Davidu: »Danes,« po tako dolgem času; kakor je rečeno: »Če boste danes zaslišali njegov glas, ne zakrknite svojih src.«',
        8: 'Kajti če jim je Jezus dal počitek, potem pozneje ne bi govoril o drugem dnevu.',
        9: 'Zaradi tega ostaja [šabatni] počitek za Božje ljudi.',
        10: 'Kajti kdor je vstopil v njegov počitek, je tudi prenehal s svojimi lastnimi deli, kakor je Bog s svojimi.',
        11: 'Trudimo se torej, da vstopimo v ta počitek, da ne bi katerikoli človek padel po istem zgledu nevere.',
        12: 'Kajti Božja beseda je živa in močna in ostrejša kakor vsak dvorezen meč, ki prodre celó do ločitve duše in duha, sklepov in mozga ter je razpoznavalka misli in namenov srca.',
        13: 'Niti ni nobene stvari, ki se ne razpozna v njegovem pogledu, temveč so vse stvari razgaljene in odprte očem tistega, s katerim imamo opraviti.',
        14: 'Ker imamo veličastnega vélikega duhovnika, ki je prešel v nebesa, Jezusa, Božjega sina, torej trdno držimo svojo veroizpoved.',
        15: 'Kajti nimamo vélikega duhovnika, ki ne more biti ganjen z občutenjem naših slabosti; temveč je bil skušan v vseh ozirih, podobno kakor smo mi, vendar brez greha.',
        16: 'Pristopimo torej pogumno k prestolu milosti, da bomo lahko dosegli usmiljenje in našli milost za pomoč v času potrebe.',
    },
    5: {
        1: 'Kajti vsak véliki duhovnik, vzet izmed ljudi, je odrejen za ljudi v stvareh, ki se nanašajo na Boga, da lahko daruje tako darove kakor žrtve za grehe,',
        2: 'ki ima lahko sočutje za nevedne in za tiste, ki so izven poti; kajti tudi on sam je obdan s šibkostjo.',
        3: 'In zaradi tega razloga mora kakor za ljudi, tako tudi zase darovati za grehe.',
        4: 'In noben človek si te časti ne jemlje sam, temveč kdor je poklican od Boga, kakor je bil Aron.',
        5: 'Tako tudi Kristus ni samega sebe proslavil, da bi postal véliki duhovnik, temveč tisti, ki mu je rekel: »Ti si moj Sin, danes sem te rodil.«',
        6: 'Kakor pravi tudi na drugem mestu: »Ti si duhovnik na veke po Melkízedekovem redu.«',
        7: 'Ki je v dneh svojega mesa, ko je z močnim vpitjem in solzami daroval molitve in ponižne prošnje k njemu, ki ga je bil zmožen rešiti pred smrtjo in je bil uslišan, zato ker se je bal;',
        8: 'čeprav je bil Sin, pa se je iz stvari, ki jih je pretrpel, naučil poslušnosti;',
        9: 'in ker je postal popoln, je postal avtor večne rešitve duš vsem tistim, ki ga ubogajo;',
        10: 'véliki duhovnik, poklican od Boga, po Melkízedekovem redu.',
        11: 'O katerem imamo povedati mnogo besed in bi [jih] težko izrekel, glede na to, da ste leni za poslušanje.',
        12: 'Kajti v času, ko bi morali biti učitelji, imate potrebo, da vas nekdo ponovno uči, katera so začetna načela Božjih izrekov; in postali ste takšni, ki imajo potrebo po mleku in ne po močni hrani.',
        13: 'Kajti vsak, kdor je deležen mleka, je nevešč v besedi pravičnosti, ker je dojenček.',
        14: 'Toda močna hrana pripada tem, ki so polnoletni, torej tistim, ki imajo zaradi razloga uporabe svoja čutila trenirana, da razlikujejo tako dobro kakor zlo.',
    },
    6: {
        1: 'Zatorej pustimo načela Kristusovega nauka, nadaljujmo k popolnosti; in ne polagajmo ponovno temelja kesanja od mrtvih del in vere v Boga,',
        2: 'nauka o krščevanjih in o polaganju rok in o vstajenju mrtvih ter o večni sodbi.',
        3: 'In to bomo storili, če Bog dovoli.',
        4: 'Kajti nemogoče je za tiste, ki so bili enkrat razsvetljeni in so okusili nebeški dar in so postali soudeleženci Svetega Duha',
        5: 'in so okusili dobro Božjo besedo in moči sveta, ki pride,',
        6: 'če bodo odpadli, da se jih ponovno obnovi v kesanje, ker sami sebi na novo križajo Božjega Sina in ga izpostavljajo javni sramoti.',
        7: 'Kajti zemlja, ki posrka dež, ki pogosto pada nanjo in obrodi zelišča, primerna za tiste, ki so jo obdelovali, prejema blagoslov od Boga.',
        8: 'Toda tista, ki rodi trnje in osat, je zavrnjena in je blizu prekletstva; katere konec je, da bo požgana.',
        9: 'Toda ljubljeni, mi smo glede vas prepričani o boljših stvareh in stvareh, ki spremljajo rešitev duš, čeprav tako govorimo.',
        10: 'Kajti Bog ni krivičen, da pozabi vaše delo in trud ljubezni, ki ste ga pokazali njegovemu imenu, ker ste služili svetim in še služite.',
        11: 'In želimo, da vsak izmed vas do konca izkazuje isto vnemo k polni gotovosti upanja,',
        12: 'da ne boste leni, temveč posnemovalci teh, ki zaradi vere in potrpežljivosti podedujejo obljube.',
        13: 'Kajti ko je Bog dal Abrahamu obljubo, je prisegel pri samem sebi, ker ni mogel priseči pri nikomer večjem,',
        14: 'rekoč: »Zagotovo, z blagoslavljanjem te bom blagoslovil in z množenjem te bom pomnožil.«',
        15: '§ In tako je, potem ko je potrpežljivo vztrajal, dosegel obljubo.',
        16: 'Kajti ljudje resnično prisegajo pri večjem; in prisega za potrditev jim je konec vsega prepira.',
        17: 'V čemer je Bog, voljan dedičem obljube obilneje pokazati nespremenljivost svoje namere, to potrdil s prisego;',
        18: 'da imamo z dvema nespremenljivima izjavama, v katerih je bilo za Boga nemogoče lagati, lahko močno tolažbo mi, ki smo pobegnili zaradi zatočišča, da se oprimemo upanja, postavljenega pred nas;',
        19: 'katerega upanje imamo kakor sidro duše, tako gotovo kakor neomajno in ki vstopa v to notranjost zagrinjala;',
        20: 'kamor je za nas vstopil predhodnik, celó Jezus, postavljen [za] vélikega duhovnika na veke po Melkízedekovem redu.',
    },
    7: {
        1: 'Kajti ta Melkízedek, kralj v Salemu, duhovnik najvišjega Boga, ki je srečal Abrahama, ko se je ta vračal iz poboja kraljev in ga blagoslovil;',
        2: 'ki mu je tudi Abraham dal desetino od vsega; najprej pomeni Kralj pravičnosti in nató tudi Kralj Salema, kar je Kralj miru;',
        3: 'brez očeta, brez matere, brez porekla niti nima začetka dni niti konca življenja, toda narejen podoben Božjemu Sinu trajno ostaja duhovnik.',
        4: 'Torej preudarite, kako velik je bil ta mož, ki mu je celó očak Abraham dal desetino od plenov.',
        5: 'In resnično imajo tisti, ki so iz Lévijevih sinov, ki prejemajo službo duhovništva, zapoved, naj glede na postavo od ljudi pobirajo desetine, to je, od svojih bratov, čeprav so izšli iz Abrahamovih ledij;',
        6: 'toda on, katerega poreklo ni šteto od njih, je prejel Abrahamove desetine in blagoslovil tistega, ki je imel obljube.',
        7: 'In brez vseh ugovarjanj je manjše blagoslovljeno od boljšega.',
        8: 'In tukaj prejemajo desetine ljudje, ki umirajo, toda tam jih prejema on, o katerem je pričevano, da živi.',
        9: 'In tako lahko potemtakem rečem: »Tudi Levi, ki prejema desetine, je plačal desetine po Abrahamu.«',
        10: 'Kajti bil je še v ledjih svojega očeta, ko ga je srečal Melkízedek.',
        11: 'Če je bila torej popolnost po Lévijevem duhovništvu (kajti pod njim so ljudje prejeli postavo), kakšna je bila nadaljnja potreba, da bi nastopil drug duhovnik po Melkízedekovem redu in ne bi bil imenovan po Aronovem redu?',
        12: 'Kajti zaradi spremembe duhovništva je storjena tudi potreba po spremembi postave.',
        13: 'Kajti on, o katerem se govorijo te stvari, pripada drugemu rodu, od katerega noben človek ni daroval prisotnost pri oltarju.',
        14: 'Kajti očitno je, da naš Gospod izvira iz Juda, iz rodu, o katerem glede duhovništva Mojzes ni ničesar rekel.',
        15: 'In še mnogo bolj očitno je, kajti po Melkízedekovi podobnosti vstaja drug duhovnik,',
        16: 'ki ni postal po postavi mesene zapovedi, temveč po moči neskončnega življenja.',
        17: 'Kajti on pričuje: »Ti si duhovnik na veke po Melkízedekovem redu.«',
        18: 'Kajti razveljavitev prejšnje zapovedi je resnična zaradi njene slabosti in nekoristnosti.',
        19: 'Kajti postava ni ničesar storila popolno, toda vpeljava boljšega upanja je; po katerem se bližamo k Bogu.',
        20: 'In še toliko bolj, ker ni bil narejen za duhovnika brez prisege;',
        21: '(kajti ti duhovniki so postali brez prisege; toda ta s prisego po tistem, ki mu je rekel: »Gospod je prisegel in se ne bo kesal: ›Ti si duhovnik na veke po Melkízedekovem redu‹«).',
        22: 'S tem je bil Jezus postavljen za pôroka boljše zaveze.',
        23: 'In onih je bilo resnično mnogo duhovnikov, ker jim zaradi smrti ni bilo dopuščeno, da ostanejo;',
        24: 'toda ta človek, ker ostaja večno, ima nespremenljivo duhovništvo.',
        25: 'Zatorej jih je tudi zmožen rešiti do zadnjega, da po njem pridejo k Bogu, glede na to, da vedno živi, da posreduje zanje.',
        26: 'Kajti takšen véliki duhovnik nam je bil primeren, ki je svet, neškodljiv, neomadeževan, ločen od grešnikov in je postal višji od nebes;',
        27: 'ki mu ni treba vsak dan, kakor tistim vélikim duhovnikom, darovati žrtvovanje, najprej za svoje lastne grehe in potem za grehe ljudi. Kajti to je storil enkrat, ko je daroval samega sebe.',
        28: 'Kajti postava dela ljudi [za] vélike duhovnike, ki imajo šibkost; toda beseda prisege, ki je bila, odkar [je] postava, postavlja Sina, ki je posvečen na vékomaj.',
    },
    8: {
        1: 'Torej od stvari, ki smo jih govorili, je to povzetek: ›Imamo takšnega vélikega duhovnika, ki je postavljen na desnico prestola Veličanstva v nebesih;',
        2: 'služabnika svetišča in resničnega šotorskega svetišča, ki ga je postavil Gospod in ne človek.‹',
        3: 'Kajti vsak véliki duhovnik je določen, da daruje darove in žrtve, zato je potrebno, da ima tudi ta človek nekaj, da daruje.',
        4: 'Kajti če bi bil na zemlji, ne bi bil duhovnik, glede na to, da so tu duhovniki, ki darujejo daritve glede na postavo;',
        5: 'ki služijo zgledu in senci nebeških stvari, kakor je bil Mojzes opomnjen od Boga, ko je bil na tem, da postavi šotorsko svetišče, kajti: »Glej,« pravi, » da narediš vse stvari glede na zgled, ki ti je bil pokazan na gori.«',
        6: 'Toda sedaj je dosegel toliko odličnejšo službo, kolikor je tudi posrednik boljše zaveze, ki je bila osnovana na boljših obljubah.',
        7: 'Kajti če bi bila tista prva zaveza brezhibna, potem se ne bi iskalo prostora za drugo.',
        8: 'Kajti ko je pri njih našel krivdo, jim pravi: »Glejte, pridejo dnevi, govori Gospod, ko bom z Izraelovo hišo in z Judovo hišo sklenil novo zavezo;',
        9: 'ne glede na zavezo, ki sem jo sklenil z njihovimi očeti na dan, ko sem jih prijel za roko, da jih izpeljem iz egiptovske dežele; ker niso ostali v moji zavezi in se nisem ozrl nanje,« govori Gospod.',
        10: '»Kajti to je zaveza, ki jo bom sklenil z Izraelovo hišo po tistih dneh,« govori Gospod, »svoje postave bom položil v njihove misli in jih zapisal v njihova srca, in jaz jim bom Bog in oni mi bodo ljudje;',
        11: 'in ne bodo učili vsak svojega bližnjega in vsak svojega brata, rekoč: ›Spoznajte Gospoda,‹ kajti vsi me bodo poznali, od najmanjšega do največjega.',
        12: 'Kajti usmiljen bom do njihovih nepravičnosti in njihovih grehov ter njihovih krivičnosti se ne bom več spominjal.«',
        13: 'Ker pravi: »Novo zavezo,« je prvo naredil staro. Torej to, kar propada in postaja staro, je pripravljeno, da izgine proč.',
    },
    9: {
        1: 'Torej prva zaveza je resnično imela tudi odredbe o bogoslužju in posvetnem svetišču.',
        2: 'Kajti postavljeno je bilo šotorsko svetišče; prvo, v katerem je bil svečnik in miza ter hlebi navzočnosti; kar je imenovano Svetišče.',
        3: 'Za drugim zagrinjalom pa šotorsko svetišče, ki se imenuje Najsvetejše;',
        4: 'ki je imelo zlato kadilnico in skrinjo zaveze v celoti prevlečeno z zlatom, v kateri je bila zlata posoda, ki je imela mano in Aronova palica, ki je vzbrstela ter plošči zaveze;',
        5: 'in nad njo keruba slave, ki zasenčujeta sedež milosti [skrinje zaveze]; o katerem sedaj ne moremo podrobno govoriti.',
        6: 'Torej ko so bile te stvari tako odrejene, so duhovniki, opravljajoč službo Bogu, vedno šli v prvo šotorsko svetišče.',
        7: 'Toda v drugo je véliki duhovnik odšel sam, enkrat vsako leto, ne brez krvi, ki jo je daroval zase in za grehe ljudi.',
        8: 'Sveti Duh tako naznanja, da pot v najsvetejše še ni bila razodeta, dokler je še stalo prvo šotorsko svetišče.',
        9: 'Ta je bil podoba za tedaj pripravljeni čas, v katerem so bili darovani tako darovi kakor žrtve, ki niso mogli storiti popolnega, kar se tiče vesti, tistega, ki je službo opravljal.',
        10: 'To je veljalo samo za jedi in pijače in številna umivanja ter mesene odredbe, naložene nanje do časa preureditve.',
        11: 'Toda Kristus, ki je prišel [kot] véliki duhovnik prihodnjih dobrih stvari, z večjim in popolnejšim šotorskim svetiščem, ne narejenim z rokami, to se pravi, ne od te zgradbe;',
        12: 'niti ne s krvjo koz in telet, temveč je s svojo lastno krvjo enkrat vstopil v sveti prostor in za nas dosegel večno odkupitev.',
        13: 'Kajti če kri bikov in kozlov ter pepel telice, škropeč nečiste, posvečuje do očiščenja mesa;',
        14: 'koliko bolj bo Kristusova kri, ki je po večnem Duhu samega sebe brez madeža daroval Bogu, očistila vašo vest pred mrtvimi deli, da služite živemu Bogu?',
        15: 'In zaradi tega razloga je on posrednik nove zaveze, da bi s pomočjo smrti, za odkupitev od prestopkov, ki so bili pod prvo zavezo, tisti, ki so poklicani, lahko prejeli obljubo večne dediščine.',
        16: 'Kajti kjer je oporoka, tam mora biti tudi potreba po smrti oporočnika.',
        17: 'Kajti oporoka je veljavna potem, ko so ljudje mrtvi; sicer nima nobene moči, vse dokler oporočnik živi.',
        18: 'Nakar niti prva zaveza ni bila posvečena brez krvi.',
        19: 'Kajti ko je Mojzes vsem ljudem govoril vsak predpis, glede na postavo, je vzel kri telet in kozlov, z vodo in škrlatno volno ter izop in poškropil tako knjigo kakor vse ljudi,',
        20: 'rekoč: »To je kri zaveze, ki vam jo je Bog ukazal.«',
        21: 'Poleg tega je s krvjo poškropil tako šotorsko svetišče kakor vse posode za služenje.',
        22: 'In skoraj vse stvari se po postavi očiščuje s krvjo; in brez prelivanja krvi ni odpuščanja.',
        23: 'Bilo je torej potrebno, da naj bi bili vzori stvari v nebesih očiščeni s temi; toda same nebeške stvari [pa] z boljšimi žrtvami kakor te.',
        24: 'Kajti Kristus ni vstopil v svete prostore, narejene z rokami, ki so slike resničnih; temveč v sama nebesa, da se sedaj za nas pokaže v Božji prisotnosti.',
        25: 'Niti ne, da bi samega sebe pogosto daroval, kakor véliki duhovnik vsako leto s krvjo drugih vstopa v sveti prostor;',
        26: 'kajti potem bi moral od ustanovitve sveta pogosto trpeti. Toda sedaj se je prikazal enkrat ob koncu sveta, da z žrtvovanjem samega sebe odstrani greh.',
        27: 'In kakor je določeno ljudem enkrat umreti, toda po tem sodba;',
        28: 'tako je bil Kristus enkrat darovan, da nosi grehe mnogih; in tem, ki ga pričakujejo, se bo drugič prikazal brez greha v rešitev duš.',
    },
    10: {
        1: 'Kajti postava, ki vsebuje senco dobrih stvari, ki pridejo in ne prave podobe stvari, s temi žrtvami, ki jih leto za letom stalno darujejo, še prišlecev nikoli ne more storiti popolnih.',
        2: 'Kajti ali takrat ne bi nehali biti darovani? Zato ker ti oboževalci, enkrat očiščeni, naj ne bi imeli nič več zavedanja o grehih.',
        3: 'Toda s temi daritvami je vsako leto storjen ponoven opomin zaradi grehov.',
        4: 'Kajti ni mogoče, da naj bi kri bikov in kozlov odvzemala grehe.',
        5: 'Zato, ko prihaja na svet, pravi: »Žrtvovanja in daritve nočeš, toda telo si mi pripravil;',
        6: 'v žgalnih daritvah in daritvah za greh nimaš nobenega veselja.',
        7: 'Tedaj sem rekel: ›Glej, prihajam (v zvitku knjige je to zapisano o meni), da izpolnim tvojo voljo, oh Bog.‹«',
        8: 'Še več, ko je rekel: »Žrtve in darovanja in žgalnih daritev ter darovanja za greh nočeš niti nimaš veselja v teh,« ki so darovane po postavi;',
        9: '§ je potem rekel: »Glej, prihajam, da izpolnim tvojo voljo, oh Bog.« Odpravlja prvo, da lahko vzpostavi drugo.',
        10: 'Po tej volji smo z daritvijo telesa Jezusa Kristusa posvečeni enkrat za vselej.',
        11: 'In vsak duhovnik vsak dan stoji, služi in pogosto daruje iste žrtve, ki nikoli ne morejo odvzeti grehov.',
        12: 'Toda ta človek, potem ko je daroval eno žrtev za grehe na veke, je sédel na Božjo desnico;',
        13: 'in od tega časa naprej čaka, dokler ne bodo njegovi sovražniki narejeni [za] njegovo pručko.',
        14: 'Kajti z eno daritvijo je na veke izpopolnil te, ki so posvečeni.',
        15: 'O tem nam je priča tudi Sveti Duh; kajti potem ko nam je prej rekel:',
        16: '»To je zaveza, ki jo bom sklenil z njimi po tistih dneh,« govori Gospod, »svoje postave bom položil v njihova srca in v njihove misli jih bom zapisal;',
        17: 'in njihovih grehov ter krivičnosti se ne bom več spominjal.«',
        18: 'Torej kjer je odpuščanje le-teh, ni več daritve za greh.',
        19: 'Ker imamo torej, bratje, hrabrost, da po Jezusovi krvi vstopimo v najsvetejše,',
        20: 'po novi in živi poti, ki jo je za nas posvetil skozi zagrinjalo, to se pravi svoje meso;',
        21: 'in ker imamo vélikega duhovnika nad Božjo hišo;',
        22: 'se približajmo z resničnim srcem, v polni gotovosti vere, ker smo naša srca poškropili pred zlo vestjo in naša telesa umili s čisto vodo.',
        23: 'Trdno, brez omahovanja, se držimo veroizpovedi naše vere (ker je zvest on, ki je obljubil)',
        24: 'in preudarimo drug drugega, da spodbujamo k ljubezni in k dobrim delom.',
        25: 'Ne zapuščajmo zbiranja nas samih, kakor je navada nekaterih, temveč drug drugega spodbujajmo in [to] toliko bolj, kakor vidite, da se približuje dan.',
        26: 'Kajti če namerno grešimo, potem ko smo prejeli spoznanje o resnici, za grehe ne ostane nobena žrtev več,',
        27: 'temveč neizogibno strašno pričakovanje sodbe in ognjene vročine, ki bo požrla nasprotnike.',
        28: 'Kdor je preziral Mojzesovo postavo, je na osnovi dveh ali treh prič brez usmiljenja umrl.',
        29: 'Predvidevajte, koliko hujše kazni bo vreden tisti, ki je pod stopalom pomendral Božjega Sina in je štel kri zaveze, s katero je bil posvečen, za nesveto stvar in [to] storil navzlic Duhu milosti?',
        30: 'Kajti poznamo tistega, ki je rekel: »Maščevanje pripada meni, jaz bom poplačal,« govori Gospod. In ponovno: »Gospod bo sodil svoje ljudi.«',
        31: 'To je strašna stvar, pasti v roke živega Boga.',
        32: 'Toda spomnite se prejšnjih dni, v katerih ste, potem ko ste bili razsvetljeni, pretrpeli velik boj stisk;',
        33: 'deloma, medtem ko ste bili narejeni [za] predmet zaničevanja, tako z grajami kakor s stiskami, in deloma medtem ko ste postali družabniki teh, ki so bili tega navajeni.',
        34: '§ Kajti do mene ste imeli sočutje v mojih vezeh in ste radostno sprejeli plenjenje svojih dobrin, vedoč v sebi, da imate v nebesih boljše in trajno imetje.',
        35: 'Ne odvrzite torej svoje zaupnosti, ki ima veliko povračilo nagrade.',
        36: 'Kajti potrebo imate po potrpežljivosti, da potem ko ste storili Božjo voljo, lahko prejmete obljubo.',
        37: 'Kajti še malo časa in on, ki prihaja, bo prišel in ne bo okleval.',
        38: 'Torej pravični bo živel iz vere. Toda če se kdorkoli umakne, moja duša nad njim ne bo imela veselja.',
        39: 'Toda mi nismo od teh, ki se umikajo v pogubo, temveč od teh, ki verujejo v rešitev duše.',
    },
    11: {
        1: 'Vera je torej zagotovilo stvarem, v katere upamo, dokaz nevidnih stvari.',
        2: 'Kajti po njej so starešine dosegli dober glas.',
        3: 'Po veri razumemo, da so bili svetovi zasnovani po Božji besedi, tako da stvari, ki so vidne, niso bile narejene iz stvari, ki se kažejo.',
        4: 'Po veri je Abel Bogu daroval odličnejšo žrtev kakor Kajn, s katero je dosegel pričevanje, da je bil pravičen, ker je Bog pričeval o njegovih darovih; in po njih, čeprav mrtev, še vedno govori.',
        5: 'Po veri je bil Henoh prestavljen, da ne bi videl smrti; in ni ga bilo najti, ker ga je Bog prestavil, kajti pred njegovo prestavitvijo je imel to pričevanje, da je ugajal Bogu.',
        6: 'Toda brez vere mu je nemogoče ugajati, kajti kdor prihaja k Bogu, mora verovati, da on je in da je nagrajevalec teh, ki ga marljivo iščejo.',
        7: '§ Po veri je Noe, ki je bil posvarjen od Boga, o še nevidenih stvareh, prevzet s strahom, pripravil barko za rešitev svoje hiše, po kateri je obsodil svet in postal dedič pravičnosti, ki je po veri.',
        8: 'Po veri je Abraham ubogal, ko je bil poklican, da gre ven, na kraj, ki naj bi ga kasneje prejel v dediščino; in odšel je ven, ne vedoč kam je šel.',
        9: 'Po veri se je mudil v obljubljeni deželi kot v tuji deželi in prebival v šotorih z Izakom in Jakobom, z njim sodedičema iste obljube;',
        10: 'kajti iskal je mesto, ki ima temelje, katerega graditelj in izdelovalec je Bog.',
        11: 'Preko vere je tudi sama Sara prejela moč, da spočne seme in rodila otroka, ko je bila čez starost, ker je tega, ki je obljubil, precenila zvestega.',
        12: 'Zatorej jih je izšlo celó iz enega in skoraj mrtvega, tako velika množica kakor zvezd neba in kakor peska, ki je brezštevilen ob morski obali.',
        13: 'Vsi ti so umrli v veri in niso prejeli obljub, vendar so jih videli od daleč in bili prepričani o njih in jih sprejeli ter priznali, da so bili tujci in romarji na zemlji.',
        14: 'Kajti tisti, ki govorijo takšne stvari, odkrito razglašajo, da iščejo domovino.',
        15: 'In resnično, če bi razmišljali o tej domovini, od koder so izšli, bi mogoče imeli priložnost, da se vrnejo.',
        16: 'Toda odslej si želijo boljšo domovino, to je, nebeško. Zato Bog ni osramočen, da se imenuje njihov Bog, kajti zanje je pripravil mesto.',
        17: 'Po veri je Abraham, ko je bil preizkušan, daroval Izaka. In on, ki je prejel obljube, je daroval svojega edinorojenega sina,',
        18: 'o katerem je bilo rečeno: ›Da se bo tvoje seme imenovalo po Izaku,‹',
        19: 'ker je menil, da ga je bil Bog zmožen obuditi celó od mrtvih; od koder ga je po podobi tudi prejel.',
        20: 'Po veri je, glede na stvari, ki pridejo, Izak blagoslovil Jakoba in Ezava.',
        21: 'Po veri je Jakob, ko je umiral, blagoslovil oba Jožefova sinova, in oboževal oprt na vrh svoje palice.',
        22: 'Po veri je Jožef, ko je umiral, naredil omembo odhoda Izraelovih otrok in dal zapoved glede svojih kosti.',
        23: 'Po veri so Mojzesa, ko je bil rojen, njegovi starši tri mesece skrivali, ker so videli, da je bil čeden otrok, in se niso bali kraljeve zapovedi.',
        24: 'Po veri je Mojzes, ko je prišel v leta, odklonil, da bi bil imenovan sin faraonove hčere;',
        25: 'raje si je izbral, da z Božjimi ljudmi trpi stisko, kakor da nekaj časa uživa zadovoljstva greha;',
        26: 'Kristusovo grajanje je cenil za večja bogastva kakor zaklade v Egiptu, kajti imel je spoštovanje do povračila nagrade.',
        27: 'Po veri je zapustil Egipt in se ni bal kraljevega besa, kajti vztrajal je, kakor [bi] zrl tistega, ki je neviden.',
        28: 'Prek vere je praznoval pasho in škropljenje s krvjo, da se jih ne bi dotaknil tisti, ki je uničil prvorojence.',
        29: 'Po veri so šli skozi Rdeče morje, kakor po kopni zemlji, kar so poskušali storiti Egipčani, [pa] so bili utopljeni.',
        30: 'Po veri so padli dol zidovi Jerihe, potem ko so jo obkrožali sedem dni.',
        31: 'Po veri pocestnica Rahába, ko je v miru sprejela oglednika, ni umrla s temi, ki niso verovali.',
        32: 'In kaj naj še rečem? Kajti zmanjkalo bi mi časa, da vam povem o Gideónu in o Baráku in o Samsonu in o Jefteju; tudi o Davidu in Samuelu ter o prerokih,',
        33: 'ki so po veri podjarmljali kraljestva, izvrševali pravičnost, dosegali obljube, mašili gobce levom,',
        34: 'gasili silovitost ognja, pobegnili rezilu meča, iz slabosti postajali močni, v boju postajali hrabri, vojske neznancev obračali v beg.',
        35: 'Ženske so ponovno prejemale svoje mrtve, dvignjene v življenje. Drugi pa so bili mučeni, ker niso sprejeli osvoboditve; da bi lahko dosegli boljše vstajenje;',
        36: 'in drugi so imeli preizkušnjo krutih zasmehovanj ter bičanj, da, poleg tega vezi in ujetništvo.',
        37: 'Bili so kamnani, bili so žagani narazen, bili so skušani, bili so umorjeni z mečem. Okoli so tavali v ovčjih in kozjih kožah; bili so v pomanjkanju, užaloščeni, mučeni',
        38: '(katerih svet ni bil vreden). Tavali so po puščavah in po gorah in po brlogih in zemeljskih votlinah.',
        39: 'In vsi ti, ki so prek vere dosegli dober glas, niso prejeli obljube,',
        40: 'kajti Bog je za nas priskrbel neko boljšo stvar, da oni ne bi postali popolni brez nas.',
    },
    12: {
        1: 'Zato vidite, ker smo tudi mi obdani naokoli s tako velikim oblakom pričevalcev, odložimo vsako breme in greh, ki nas tako z lahkoto pesti in s potrpežljivostjo tecimo tekmo, ki je postavljena pred nas;',
        2: 'glejmo k Jezusu, avtorju in dopolnitelju naše vere; ki je zaradi radosti, ki je bila postavljena predenj, pretrpel križ in preziral sramoto in je posedèn na desnico Božjega prestola.',
        3: 'Kajti razmislite vendar o tistem, ki je prestal takšno nasprotovanje grešnikov proti sebi, da ne bi bili vi utrujeni in oslabeli v svojih umih.',
        4: 'Niste se še do krvi uprli v boju zoper greh.',
        5: 'In pozabili ste na spodbujanje, ki vam govori kakor otrokom: »Moj sin, ne preziraj Gospodovega karanja niti ne izgubljaj poguma, kadar te ošteva;',
        6: 'kajti kogar Gospod ljubi, strogo vzgaja, in biča vsakega sina, ki ga sprejema.«',
        7: 'Če ste prestali vzgojo, Bog z vami ravna kakor s sinovi; kajti kakšen sin je ta, ki ga oče ne bi strogo vzgajal?',
        8: 'Toda če ste brez vzgoje, česar so vsi soudeleženi, potem ste nezakonski otroci, ne pa sinovi.',
        9: 'Nadalje smo imeli očete svojega mesa, ki so nas vzgajali in smo jim dali spoštovanje. Mar ne bomo veliko raje v podrejenosti Očetu duhov in živeli?',
        10: 'Kajti oni so nas resnično strogo vzgajali za nekaj dni, po svoji lastni volji; toda on za našo korist, da mi lahko postanemo soudeleženci njegove svetosti.',
        11: 'Torej nobeno opominjanje zaenkrat ni videti, da bi bilo veselo, temveč bridko. Kljub temu potem obrodi miren sad pravičnosti v teh, ki so z njim izurjeni.',
        12: 'Zatorej dvignite roke, ki visijo in slabotna kolena;',
        13: 'in naredite ravne steze za svoja stopala, da se ne bi to, kar šepa, obrnilo proč s poti, temveč naj bo raje ozdravljeno.',
        14: 'Prizadevajte si za mir z vsemi ljudmi in svetost, brez katere noben človek ne bo videl Gospoda.',
        15: 'Marljivo zrite, da ne bi katerikoli človek padel od Božje milosti; da vas ne bi zbegala nobena korenina grenkobe, ki poganja in bi bili z njo mnogi omadeževani;',
        16: 'da ne bi bilo nobenega prešuštvovalca ali oskrunjene osebe, kakor Ezav, ki je za en košček hrane prodal pravico svojega prvorojenstva.',
        17: 'Kajti veste, kako je bil potem, ko je želel podedovati blagoslov, zavrnjen; kajti ni našel nobenega prostora za kesanje, čeprav ga je skrbno iskal s solzami.',
        18: 'Kajti niste prišli h gori, ki se jo lahko dotakne in ki gori z ognjem in niti k črnosti in ne temi in ne viharju',
        19: 'in ne donenju trobente in ne glasu besed; katerega glas so tisti, ki so poslušali, rotili, da jim beseda ne bi bila več izgovorjena.',
        20: '§ (Kajti niso mogli prenesti tega, kar je bilo ukazano: »In če se žival komaj dotakne gore, naj bo kamnana ali prebodena s puščico.«',
        21: 'In prizor je bil tako strašen, da je Mojzes rekel: »Silno se bojim in tresem.«)',
        22: 'Toda vi ste prišli h gori Sion in k mestu živega Boga, nebeškemu Jeruzalemu in k nepreštevni angelski druščini,',
        23: 'h glavnemu zboru in cerkvi prvorojenih, ki so zapisani v nebesih in k Bogu, Sodniku vseh in k duhovom pravičnih ljudi, ki so dosegli popolnost',
        24: 'in k Jezusu, posredniku nove zaveze in h krvi škropljenja, ki govori boljše stvari kakor ta od Abela.',
        25: 'Glejte, da ne zavrnete tistega, ki govori. Kajti če niso ušli tisti, ki so zavrnili tistega, ki je govoril na zemlji, koliko bolj ne bomo ušli mi, če se odvrnemo od tistega, ki govori iz nebes;',
        26: 'katerega glas je takrat stresel zemljo; toda sedaj je obljubil, rekoč: »Še enkrat stresem, ne samo zemljo, temveč tudi nebo.«',
        27: 'In ta beseda: »Še enkrat,« pomeni odstranitev tistih stvari, ki so lahko stresene, kakor od stvari, ki so narejene, da te stvari, ki ne morejo biti stresene, lahko ostanejo.',
        28: 'Zaradi tega mi, ki prejemamo kraljestvo, ki ne more biti omajano, imejmo milost, s katero lahko sprejemljivo služimo Bogu, s spoštovanjem in bogaboječim strahom.',
        29: 'Kajti naš Bog je požirajoč ogenj.',
    },
    13: {
        1: 'Naj se bratoljúbje nadaljuje.',
        2: '§ Ne bodite pozabljivi, da pogostite tujce, kajti s tem so nekateri nevedoč pogostili angele.',
        3: 'Spominjajte se teh, ki so v vezeh kakor zvezani z njimi; in teh, ki prenašajo nadloge, kakor ste tudi vi sami v telesu.',
        4: 'Zakon je častitljiv v vsem in postelja neomadeževana, toda vlačugarje in zakonolomce bo sodil Bog.',
        5: 'Naj bo vaše vedênje brez pohlepnosti in bodite zadovoljni s temi stvarmi, kar jih imate; kajti rekel je: »Nikoli te ne bom zapustil niti se te ne bom odrekel.«',
        6: 'Tako da lahko pogumno rečemo: »Gospod je moj pomočnik in ne bom se bal, kaj mi bo storil človek.«',
        7: 'Spominjajte se teh, ki imajo nad vami vladarstvo, ki so vam govorili Božjo besedo; katerih vero posnemajte in upoštevajte konec njihovega vedênja.',
        8: 'Jezus Kristus, isti včeraj in danes in na veke.',
        9: 'Ne bodite nošeni naokoli z različnimi in tujimi nauki. Kajti dobra stvar je, da je srce utrjeno z milostjo; ne [pa] z jedmi, ki niso koristile tem, ki so bili zavzeti s tem.',
        10: 'Imamo oltar, s katerega nimajo pravice jesti tisti, ki služijo šotorskemu svetišču.',
        11: 'Kajti telesa teh živali, katerih kri prinese véliki duhovnik v svetišče za greh, so zažgana zunaj šotorišča.',
        12: 'Zato je tudi Jezus, da je lahko s svojo lastno krvjo ljudi posvetil, trpel zunaj velikih vrat.',
        13: 'Zato pojdimo naprej k njemu zunaj šotorišča in prenašajmo njegovo grajo.',
        14: 'Kajti tukaj nimamo trajnega mesta, temveč iščemo tega, ki pride.',
        15: 'Po njem torej Bogu nenehno darujmo hvalno žrtev, to je, sad naših ustnic, ki dajejo zahvalo njegovemu imenu.',
        16: 'Toda ne pozabite delati dobro in razdeljevati, kajti s takšnimi žrtvami je Bog zelo zadovoljen.',
        17: 'Ubogajte te, ki imajo vladarstvo nad vami in se podredite; kajti oni bedijo nad vašimi dušami kakor tisti, ki morajo dati obračun, da bodo to lahko delali z radostjo in ne z žalostjo, kajti to je za vas nekoristno.',
        18: 'Molite za nas, kajti zaupamo, [da] imamo dobro vest [in smo] v vseh stvareh voljni iskreno živeti.',
        19: 'Toda rotim vas, raje delajte to, da vam bom lahko prej vrnjen.',
        20: 'Torej Bog miru, ki je od mrtvih ponovno privedel našega Gospoda Jezusa, ta véliki pastir ovc, naj vas po krvi večne zaveze,',
        21: 'naredi popolne v vsakem dobrem delu, da izpolnite njegovo voljo, ki povzroča v vas to, kar je prijetno v njegovem pogledu, po Jezusu Kristusu, ki mu bodi slava na veke vekov. Amen.',
        22: 'In rotim vas, bratje, dopustite besedo opominjanja, kajti pismo sem vam napisal z nekaj besedami.',
        23: 'Védite, da je naš brat Timótej izpuščen na prostost; s katerim, če pride v kratkem, vas bom videl.',
        24: 'Pozdravite vse tiste, ki vladajo nad vami in vse svete. Pozdravljajo vas tisti iz Italije.',
        25: 'Milost bodi z vami vsemi. Amen. [Napisano Hebrejcem iz Italije po Timóteju.]',
    },
}
